#include <stdlib.h>

int main(void)
{
    int n, i;
    long long target;
    long long *a, *left, *right;

    if (scanf("%d %lld", &n, &target) != 2 || n <= 0)
        return 0;

    a = (long long *)malloc((size_t)n * sizeof(long long));
    if (a == NULL)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%lld", &a[i]);

    left = a;              /* 指向第一个元素 */
    right = a + n - 1;     /* 指向最后一个元素 */

    while (left < right) {
        long long sum = *left + *right;
        if (sum == target)
            break;
        if (sum < target)
            left++;        /* 和偏小，左端右移让和变大 */
        else
            right--;       /* 和偏大，右端左移让和变小 */
    }

    if (left < right)
        printf("%d %d\n", (int)(left - a) + 1, (int)(right - a) + 1);
    else
        puts("NO");

    free(a);
    return 0;
}

