    for (long long &x : a)
        std::cin >> x;

    int left = 0, right = n - 1;
    while (left < right) {
        long long sum = a[left] + a[right];
        if (sum == target)
            break;
        if (sum < target)
            ++left;
        else
            --right;
    }

    if (left < right)
        std::cout << left + 1 << ' ' << right + 1 << '\n';
    else
        std::cout << "NO\n";

    return 0;
}

