#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void free_all(char **arr, int cnt)
{
    int k;
    for (k = 0; k < cnt; k++)
        free(arr[k]);
    free(arr);
}

static int cmp(const void *pa, const void *pb)
{
    const char *a = *(const char *const *)pa;
    const char *b = *(const char *const *)pb;
    size_t la = strlen(a), lb = strlen(b);

    if (la != lb)
        return la < lb ? -1 : 1;
    return strcmp(a, b);
}

int main(void)
{
    int n, i;
    char buf[64];
    char **arr;

    if (scanf("%d", &n) != 1 || n <= 0)
        return 0;

    arr = (char **)malloc((size_t)n * sizeof(char *));
    if (arr == NULL)
        return 1;

    for (i = 0; i < n; i++) {
        size_t len;

        if (scanf("%63s", buf) != 1)
            buf[0] = '\0';

        len = strlen(buf);
        arr[i] = (char *)malloc(len + 1);
        if (arr[i] == NULL) {
            free_all(arr, i);
            return 1;
        }
        memcpy(arr[i], buf, len + 1);
    }

    qsort(arr, (size_t)n, sizeof(char *), cmp);

    for (i = 0; i < n; i++)
        puts(arr[i]);

    free_all(arr, n);
    return 0;
}

