#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

static Node *create_node(int v)
{
    Node *p = (Node *)malloc(sizeof(Node));
    if (p != NULL) {
        p->val = v;
        p->next = NULL;
    }
    return p;
}

static void destroy(Node *head)
{
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

int main(void)
{
    Node *head = NULL, *tail = NULL;
    Node *p, *pre;
    int v, count = 0;

    /* 尾插法建表 */
    while (scanf("%d", &v) == 1 && v != -1) {
        Node *node = create_node(v);
        if (node == NULL) {
            destroy(head);
            return 1;
        }
        if (head == NULL)
            head = node;
        else
            tail->next = node;
        tail = node;
    }

    /* 对每个结点，回看它前面是否出现过相同的值 */
    pre = NULL;
    p = head;
    while (p != NULL) {
        Node *q = head;
        int dup = 0;

        while (q != p) {
            if (q->val == p->val) {
                dup = 1;
                break;
            }
            q = q->next;
        }

        if (dup) {
            pre->next = p->next;   /* p 不是首结点，pre 一定非空 */
            free(p);
            p = pre->next;
        } else {
            pre = p;
            p = p->next;
        }
    }

    for (p = head; p != NULL; p = p->next)
        count++;
    printf("%d\n", count);

    if (count > 0) {
        int first = 1;
        for (p = head; p != NULL; p = p->next) {
            if (!first)
                putchar(' ');
            printf("%d", p->val);
            first = 0;
        }
        putchar('\n');
    }

    destroy(head);
    return 0;
}

