struct Node {
    int val;
    Node *next;
    explicit Node(int v) : val(v), next(nullptr) {}
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    Node *head = nullptr, *tail = nullptr;
    int v;
    while (std::cin >> v && v != -1) {
        Node *node = new Node(v);
        if (head == nullptr)
            head = node;
        else
            tail->next = node;
        tail = node;
    }

    std::unordered_set<int> seen;
    Node *pre = nullptr, *cur = head;
    while (cur != nullptr) {
        if (!seen.insert(cur->val).second) {   /* 已经出现过，删除 */
            pre->next = cur->next;
            delete cur;
            cur = pre->next;
        } else {
            pre = cur;
            cur = cur->next;
        }
    }

    int count = 0;
    for (Node *p = head; p != nullptr; p = p->next)
        ++count;
    std::cout << count << '\n';

    if (count > 0) {
        bool first = true;
        for (Node *p = head; p != nullptr; p = p->next) {
            if (!first)
                std::cout << ' ';
            std::cout << p->val;
            first = false;
        }
        std::cout << '\n';
    }

    while (head != nullptr) {
        Node *next = head->next;
        delete head;
        head = next;
    }
    return 0;
}

