    if (scanf("%d", &n) != 1 || n <= 0 || n > 100)
        return 0;

    for (i = 0; i < n; i++)
        scanf("%19s %19s %d", stu[i].id, stu[i].name, &stu[i].score);

    qsort(stu, (size_t)n, sizeof(Student), cmp);

    for (i = 0; i < n; i++) {
        if (i == 0 || stu[i].score != stu[i - 1].score)
            rank = i + 1;
        printf("%d %s %s %d\n", rank, stu[i].id, stu[i].name, stu[i].score);
    }

