/* 递归快速幂：返回 a^n mod m */
static long long pow_mod(long long a, unsigned long long n, long long m)
{
    long long half, res;

    if (n == 0)
        return 1 % m;              /* m == 1 时结果应为 0 */

    half = pow_mod(a, n / 2, m);   /* 只递归一次，避免重复计算 */
    res = half * half % m;         /* half < m，乘积不超过 10^18 */

    if (n & 1ULL)
        res = res * (a % m) % m;   /* 奇数还要再乘一个 a */

    return res;
}

int main(void)
{
    long long a, m;
    unsigned long long n;

    if (scanf("%lld %llu %lld", &a, &n, &m) != 3 || m <= 0)
        return 0;

    printf("%lld\n", pow_mod(a % m, n, m));
    return 0;
}

