/* 第一个 >= x 的下标，返回值可能等于 n */
static int lower_bound(const int *a, int n, int x)
{
    int lo = 0, hi = n;

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

/* 第一个 > x 的下标，返回值可能等于 n */
static int upper_bound(const int *a, int n, int x)
{
    int lo = 0, hi = n;

    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] <= x)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

int main(void)
{
    int n, m, i, x;
    int *a;

    if (scanf("%d %d", &n, &m) != 2 || n <= 0)
        return 0;

    a = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL)
        return 1;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    for (i = 0; i < m; i++) {
        int first, last;

        if (scanf("%d", &x) != 1)
            break;
        first = lower_bound(a, n, x);
        if (first == n || a[first] != x) {
            puts("-1 -1");
        } else {
            last = upper_bound(a, n, x) - 1;
            printf("%d %d\n", first, last);
        }
    }

    free(a);
    return 0;
}

