/* 扩展欧几里得：返回 gcd(a, b)，并通过出参带回 x、y 使 a*x + b*y = gcd */
static long long ext_gcd(long long a, long long b, long long *x, long long *y)
{
    long long x1, y1, g;

    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }

    g = ext_gcd(b, a % b, &x1, &y1);
    *x = y1;
    *y = x1 - (a / b) * y1;
    return g;
}

int main(void)
{
    long long a, b, x = 0, y = 0, g;

    if (scanf("%lld %lld", &a, &b) != 2 || a <= 0 || b <= 0)
        return 0;

    g = ext_gcd(a, b, &x, &y);

    printf("%lld\n", g);
    printf("%lld\n", a / g * b);   /* 先除后乘，防止溢出 */
    printf("%lld %lld\n", x, y);

    return 0;
}

