#include <stdlib.h>

/* 归并排序 [lo, hi)，返回该区间内的逆序对个数 */
static long long merge_count(int *a, int *tmp, int lo, int hi)
{
    int mid, i, j, k;
    long long cnt;

    if (hi - lo <= 1)
        return 0;

    mid = lo + (hi - lo) / 2;
    cnt = merge_count(a, tmp, lo, mid) + merge_count(a, tmp, mid, hi);

    i = lo;
    j = mid;
    k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
            cnt += mid - i;    /* a[i..mid-1] 都大于 a[j] */
        }
    }
    while (i < mid)
        tmp[k++] = a[i++];
    while (j < hi)
        tmp[k++] = a[j++];
    for (i = lo; i < hi; i++)
        a[i] = tmp[i];

    return cnt;
}

int main(void)
{
    int n, i;
    int *a, *tmp;
    long long inv;

    if (scanf("%d", &n) != 1 || n <= 0)
        return 0;

    a = (int *)malloc((size_t)n * sizeof(int));
    tmp = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL || tmp == NULL) {
        free(a);
        free(tmp);
        return 1;
    }

    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    inv = merge_count(a, tmp, 0, n);

    for (i = 0; i < n; i++)
        printf("%d%c", a[i], i + 1 < n ? ' ' : '\n');
    printf("%lld\n", inv);

    free(a);
    free(tmp);
    return 0;
}

