typedef struct {
    long long l, r;
} Interval;

static int cmp(const void *pa, const void *pb)
{
    const Interval *a = (const Interval *)pa;
    const Interval *b = (const Interval *)pb;

    if (a->l != b->l)
        return a->l < b->l ? -1 : 1;
    if (a->r != b->r)
        return a->r < b->r ? -1 : 1;
    return 0;
}

int main(void)
{
    int n, i, k = 0;
    Interval *seg, *res;

    if (scanf("%d", &n) != 1 || n <= 0)
        return 0;

    seg = (Interval *)malloc((size_t)n * sizeof(Interval));
    res = (Interval *)malloc((size_t)n * sizeof(Interval));
    if (seg == NULL || res == NULL) {
        free(seg);
        free(res);
        return 1;
    }

    for (i = 0; i < n; i++)
        scanf("%lld %lld", &seg[i].l, &seg[i].r);

    qsort(seg, (size_t)n, sizeof(Interval), cmp);

    res[0] = seg[0];
    k = 1;
    for (i = 1; i < n; i++) {
        if (seg[i].l <= res[k - 1].r) {
            if (seg[i].r > res[k - 1].r)
                res[k - 1].r = seg[i].r;
        } else {
            res[k++] = seg[i];
        }
    }

    printf("%d\n", k);
    for (i = 0; i < k; i++)
        printf("%lld %lld\n", res[i].l, res[i].r);

    free(seg);
    free(res);
    return 0;
}

